package com.railyatra.booking;
import com.railyatra.auth.AuthPrincipal; import com.railyatra.passenger.*; import com.railyatra.railway.domain.*; import com.railyatra.railway.repository.TrainStopRepository; import com.railyatra.railway.service.SeatHoldService; import java.util.List; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.server.ResponseStatusException;
@Service public class CheckoutReviewService {
 private final SeatHoldService holds; private final TrainStopRepository stops; private final FareCalculatorService fareCalculator; private final PassengerService passengerService;
 public CheckoutReviewService(SeatHoldService holds,TrainStopRepository stops,FareCalculatorService fareCalculator,PassengerService passengerService){this.holds=holds;this.stops=stops;this.fareCalculator=fareCalculator;this.passengerService=passengerService;}
 @Transactional public CheckoutReviewResponse review(AuthPrincipal principal,CheckoutReviewRequest request){SeatHold hold=holds.lockActiveHoldForBooking(principal.id(),request.holdId());if(hold.getStatus()!=SeatHoldStatus.ACTIVE)throw new ResponseStatusException(HttpStatus.CONFLICT,"Seat hold has expired; recheck availability");if(request.passengers().size()!=hold.getPassengerCount())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Passenger count must match the active hold");List<PassengerDetailsRequest> normalized=passengerService.validate(new PassengerBatchRequest(request.passengers()));TrainStop from=stops.findByTrainIdAndStationStationCode(hold.getTrain().getId(),request.originStationCode().trim().toUpperCase()).orElseThrow(()->new ResponseStatusException(HttpStatus.BAD_REQUEST,"Train does not stop at origin"));TrainStop to=stops.findByTrainIdAndStationStationCode(hold.getTrain().getId(),request.destinationStationCode().trim().toUpperCase()).orElseThrow(()->new ResponseStatusException(HttpStatus.BAD_REQUEST,"Train does not stop at destination"));if(from.getStopSequence()>=to.getStopSequence())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid journey direction");return new CheckoutReviewResponse(hold.getTrain().getTrainNumber(),hold.getTrain().getTrainName(),from.getStation().getStationCode(),to.getStation().getStationCode(),hold.getJourneyDate(),from.getDepartureTime(),to.getArrivalTime(),hold.getTrainClass().getClassCode(),hold.getQuota(),normalized.stream().map(p->new CheckoutReviewResponse.Passenger(p.name(),p.age(),p.gender(),p.berthPreference())).toList(),fareCalculator.calculate(hold.getTrain(),hold.getTrainClass(),request.originStationCode(),request.destinationStationCode(),normalized.size()),hold.getExpiresAt());}
}
